INSERT INTO verses_yousafzai (id, ref, book, chapter, verse, text, text_normalized, testament, translation_key, dialect, audio_r2_key, audio_public_url, created_at, updated_at, tags) VALUES
(20901, 'Daniel 10:1', 'Daniel', 10, 1, '&nbsp;د فارس د بادشاه خورس د بادشاهۍ په درېم کال ما دانيال ته چې راته بيلطشضر هم وئيل کېدو يوه رويا راکړے شوه. د دې پېغام حقيقت وو او دا د يو لوئ جنګ په حقله وه. د رويا په وسيله زۀ په دې پېغام پوهه شوم.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(20902, 'Daniel 10:2', 'Daniel', 10, 2, '&nbsp;کله چې دا رويا ما وليده نو په هغه وخت کښې ما دانيال د درې هفتو نه ماتم کولو.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(20903, 'Daniel 10:3', 'Daniel', 10, 3, '&nbsp;ما نۀ ښۀ خوراک کړے وو،نۀ مې غوښه او نۀ مې مے خپلو شونډو ته نزدې کړى وُو، او ما د درېو هفتو د تېرېدو پورې د سر تېل هم استعمال کړى نۀ وو.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(20904, 'Daniel 10:4', 'Daniel', 10, 4, '&nbsp;د وړومبۍ مياشتې په څليريشتمه ورځ، کله چې زۀ د دجله د لوئ سيند په غاړه ولاړ وم،', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(20905, 'Daniel 10:5', 'Daniel', 10, 5, '&nbsp;هر کله چې ما بره وکتل نو ځان ته مخامخ مې يو سړے وليدو چې د سپين کتان جامې يې اغوستې وې، او د ملا نه يې د سوچه سرو زرو ملابند تړلے وو.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(20906, 'Daniel 10:6', 'Daniel', 10, 6, '&nbsp;د هغۀ بدن د ايکوامرين کاڼى په شان وو، د هغۀ مخ لکه د برېښنا په شان ځلېدو، د هغۀ سترګې لکه د مشعلونو په شان بلېدلې، د هغۀ لاسونه او پښې لکه د زېړو په شان ځلېدل، او د هغۀ آواز لکه د لوئ ګڼې د شور په شان وو.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(20907, 'Daniel 10:7', 'Daniel', 10, 7, '&nbsp;صرف ما دانيال، دا رويا وليده، ما سره نورو سړو دا ونۀ ليده، خو بيا هم هغوئ داسې وحشت واخستل چې وتښتېدل او ځانونه يې پټ کړل.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(20908, 'Daniel 10:8', 'Daniel', 10, 8, '&nbsp;نو زۀ يواځې پاتې شوم چې دا عظيمه رويا وګورم. په ما کښې طاقت پاتې نۀ شو، زما رنګ د مړى په شان تک زېړ شو او بې‌دمه شوم.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(20909, 'Daniel 10:9', 'Daniel', 10, 9, '&nbsp;نو بيا ما واورېدل چې هغۀ خبرې کولې، او څنګه چې ما هغۀ ته غوږ ونيولو، زۀ بې‌هوشه شوم، په زمکه پړمخې پرېوتلم.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(20910, 'Daniel 10:10', 'Daniel', 10, 10, '&nbsp;بيا يو لاس زۀ راونيولم او په خپل ځائ يې په لړزېدو سره په ګوډو کړم.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(20911, 'Daniel 10:11', 'Daniel', 10, 11, '&nbsp;هغۀ وفرمائيل، ”اے دانياله، تۀ خُدائ پاک ته ډېر ګران يې، کومې خبرې چې زۀ تا ته کوم هغې ته غوږ ونيسه، او پاڅه ودرېږه، ځکه چې زۀ تا له رالېږلے شوے يم.“ او کله چې هغۀ ما ته دا وفرمائيل، نو زۀ په لړزېدو سره ودرېدلم.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(20912, 'Daniel 10:12', 'Daniel', 10, 12, '&nbsp;بيا هغۀ خبره جارى وساتله، ”اے دانياله مۀ يرېږه. د وړومبۍ ورځې نه کله چې تا خپل سوچ دې ته تيار کړو چې پوهه حاصله کړې او د خُدائ پاک په وړاندې دې خپل ځان عاجز کړو، نو ستا دُعا قبوله شوه، او زۀ د هغې په جواب کښې راغلے يم.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(20913, 'Daniel 10:13', 'Daniel', 10, 13, '&nbsp;خو د فارس سلطنت روحانى شهزاده تر يوويشت ورځو پورې زما مخه ونيوله. بيا ميکائيل چې د فرښتو سردار دے، زما مدد کولو له راغلو ځکه چې زۀ د فارس بادشاه سره ګېر شوے وم.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(20914, 'Daniel 10:14', 'Daniel', 10, 14, '&nbsp;زۀ اوس راغلے يم چې تاسو ته دا تشريح کړم چې په راتلونکى وخت کښې به ستا خلقو سره څۀ کيږى، ځکه چې د دې رويا تعلق د راتلونکى وخت سره دے.“', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(20915, 'Daniel 10:15', 'Daniel', 10, 15, '&nbsp;کله چې هغۀ ما ته دا خبرې کولې نو ما لاندې زمکې ته کتل او ګونګا شوے وم.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(20916, 'Daniel 10:16', 'Daniel', 10, 16, '&nbsp;نو بيا يو لکه د انسان په شان ښکارېدو هغۀ زما شونډې مسح کړې، او ما خپله خوله کولاو کړه او خبرې مې شروع کړې. ما هغه چا ته څوک چې زما په وړاندې ولاړ وو وئيل، ”مالِکه، زۀ د دې رويا په وجه اندېښنو راګېر کړے يم او په ما کښې زور ختم شوے دے.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(20917, 'Daniel 10:17', 'Daniel', 10, 17, '&nbsp;زۀ ستا نوکر څنګه تا سره خبرې وکړم، اے زما مالِکه؟ زما زور ختم شوے دے او ساه مې ځى راځى.“', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(20918, 'Daniel 10:18', 'Daniel', 10, 18, '&nbsp;نو هغه څوک چې د بنى آدم په شان ښکارېدو زۀ يې بيا مسح کړم او ما له يې طاقت راکړو.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(20919, 'Daniel 10:19', 'Daniel', 10, 19, '&nbsp;هغۀ وفرمائيل، ”اے خُدائ پاک ته، ګران انسانه مۀ يرېږه. سلامت اوسه. اوس ډاډه شه، ډاډه شه.“ کله چې هغۀ ما سره خبرې وکړې، ما ته طاقت مِلاو شو او ورته ومې ووئيل، ”اے مالِکه اوس خبره وکړه، ځکه چې تا ما له طاقت راکړے دے.“', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(20920, 'Daniel 10:20', 'Daniel', 10, 20, '&nbsp;نو بيا هغۀ وفرمائيل چې، ”تا ته پته ده چې زۀ ولې تا له راغلے يم؟ زۀ به زر د فارس د شهزاده خلاف جنګ له واپس لاړ شم، او څنګه چې زۀ لاړ شم، د يونان شهزاده به راشى،', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(20921, 'Daniel 10:21', 'Daniel', 10, 21, '&nbsp;خو زۀ به اول تا ته هغه څۀ ووايم چې څۀ د حقيقت په کِتاب کښې ليکلے شوى دى. د دوئ خلاف هيڅ څوک هم زما مدد نۀ کوى بغېر د ميکائيل ستاسو د شهزاده نه.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(20922, 'Daniel 11:1', 'Daniel', 11, 1, '&nbsp;او د داريوس ميدى د بادشاهۍ په اول کال، زۀ ودرېدلم چې هغه مضبوط او تکړه کړم.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(20923, 'Daniel 11:2', 'Daniel', 11, 2, '&nbsp;نو بيا اوس، زۀ تاسو ته رښتيا وايم. د قومونو په خپلو کښې جنګونه په فارس کښې به نور درې بادشاهان راوچت شى، او بيا به څلورم بادشاه راشى، څوک چې به د هغوئ ټولو نه زيات مالداره وى. هغۀ د خپل دولت په ذريعه طاقت حاصل کړے دے، نو هغه به هر څوک د يونان د حکومت په خلاف راوچت کړى.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(20924, 'Daniel 11:3', 'Daniel', 11, 3, '&nbsp;نو بيا به يو زورَور بادشاه راشى او هغه به په لوئ اختيار سره بادشاهى کوى او هر څۀ چې يې زړۀ غواړى هغه به وکړى.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(20925, 'Daniel 11:4', 'Daniel', 11, 4, '&nbsp;خو د هغۀ د ښکاره کېدو نه وروستو به د هغۀ بادشاهى ټوکړې ټوکړې شى، او دا به په څلورو حِصو تقسيم شى. دا به د دۀ اولاد ته پاتې نۀ شى، او نۀ به بيا هغه داسې طاقتوره وى لکه څنګه چې اول وه، ځکه د دۀ بادشاهى به د بېخ نه ختمه شى او نورو ته به حواله کړے شى.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(20926, 'Daniel 11:5', 'Daniel', 11, 5, '&nbsp;د جنوب بادشاه به مضبوط شى، خو د هغۀ يو آفسر به د هغۀ نه زيات مضبوط شى او هغه به د هغۀ نه په زيات طاقت سره په خپلو خلقو حکومت کوى.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(20927, 'Daniel 11:6', 'Daniel', 11, 6, '&nbsp;څو کاله پس به د جنوب او د شمال بادشاه په خپلو کښې اِتحاد جوړ کړى. د جنوب د بادشاه لور به د شمال بادشاه ته د اِتحاد جوړولو دپاره وادۀ کړے شى، خو هغه به په خپل خاوند اثر رسوخ ونۀ ساتلے شى هغه او د هغې اثر رسوخ به ختم شى. نو هغه به بيا سره د خپل پلار او شاهى خِدمت کوونکو ووژلے شى.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(20928, 'Daniel 11:7', 'Daniel', 11, 7, '&nbsp;نو بيا به د هغې د خاندان نه يو کس راوچت شى چې د هغې ځائ ونيسى. او هغه به د شمال د بادشاه په فوج حمله وکړى او هغه قلعه ګانو ته به ننوځى، هغه به د هغوئ خلاف جنګ وکړى او کامياب به شى.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(20929, 'Daniel 11:8', 'Daniel', 11, 8, '&nbsp;هغه به د هغوئ معبودان، د هغوئ د پيتلو بُتان او د هغوئ قيمتى د سپينو او سرو زرو سامان قبضه کړى او ځان سره به يې مِصر ته يوسى. او د څو کالو پورې به هغه د شمال په بادشاه حمله ونۀ کړى.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(20930, 'Daniel 11:9', 'Daniel', 11, 9, '&nbsp;بيا به د شمال بادشاه د جنوب د بادشاه په سلطنت حمله وکړى خو هغه به واپس شى او خپل مُلک ته به لاړ شى.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(20931, 'Daniel 11:10', 'Daniel', 11, 10, '&nbsp;د هغۀ زامن به د جنګ دپاره تيار شى او يو لوئ لښکر به جوړ کړى، دا به لکه د سېلاب غوندې وى او جنګ به د هغۀ قلعه ګانو ته ورورسوى.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(20932, 'Daniel 11:11', 'Daniel', 11, 11, '&nbsp;بيا به د جنوب بادشاه په غصه کښې راوځى او د شمال د بادشاه په خلاف به جنګ وکړى، څوک چې به لوئ لښکر تيار کړى خو هغوئ به هم شکست وخورى.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(20933, 'Daniel 11:12', 'Daniel', 11, 12, '&nbsp;کله چې فوج تباه شى نو د جنوب بادشاه کښې به غرور راشى او هغه به په زرګونو خلق مړۀ کړى، خو هغه به د ډېر وخت پورې کامياب نۀ شى.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(20934, 'Daniel 11:13', 'Daniel', 11, 13, '&nbsp;ځکه چې د شمال بادشاه به بل لښکر راغونډ کړى، د وړومبى لښکر نه به غټ وى، او يو څو کاله پس به هغه د يو لوئ لښکر سره په هر قسمه وسلو سمبال راشى.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(20935, 'Daniel 11:14', 'Daniel', 11, 14, '&nbsp;په هغه وخت کښې به ډېر خلق د جنوب د بادشاه خلاف راپاڅى. ستا د قوم پارېدلى خلق به د رويا په پوره کېدو کښې بغاوت وکړى، خو هغوئ به کامياب نۀ شى.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(20936, 'Daniel 11:15', 'Daniel', 11, 15, '&nbsp;نو بيا به د شمال بادشاه راشى او قلعه بند ښار د قبضه کولو دپاره به د خاورو ډيرى جوړ کړى. د جنوب فوجيان به دوئ ايسارولے نۀ شى، تر دې چې د ټولو نه ښۀ او زورَور فوجيان به هم د هغوئ مقابله نۀ شى کولے.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(20937, 'Daniel 11:16', 'Daniel', 11, 16, '&nbsp;حمله کوونکے بادشاه به هم هغه څۀ کوى څۀ چې يې زړۀ غواړى، څوک به د هغۀ خلاف نۀ شى ودرېدلے. هغه به ځان په ښائسته مُلک کښې آباد کړى او هغۀ سره به د هغې د تباه کولو اختيار وى.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(20938, 'Daniel 11:17', 'Daniel', 11, 17, '&nbsp;هغه به يوه منصوبه جوړه کړى چې د خپل ټول سلطنت د زور سره راشى او هغه به د جنوب د بادشاه سره اِتحاد وکړى. او خپله لور به هغۀ ته وادۀ کړى د دې دپاره چې سلطنت تباه کړى، خو د هغۀ منصوبه به کاميابه نۀ شى او نۀ به فائده ورکړى.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(20939, 'Daniel 11:18', 'Daniel', 11, 18, '&nbsp;هغه به ساحلى علاقې خوا ته خپله توجو وګرځوى او په ډېرو علاقو به قبضه وکړى، خو د يو بل مُلک فوجى کمانډر به د هغۀ ګستاخانه رويه ختمه کړى او په شرمونو به يې وشرموى.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(20940, 'Daniel 11:19', 'Daniel', 11, 19, '&nbsp;د دې نه پس به هغه خپل مُلک کښې خپلو قلعه ګانو ته واپس شى خو هغه به تيندک وخورى او وبه غورزيږى نو د هغۀ نام و نشان به پاتې نۀ شى.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(20941, 'Daniel 11:20', 'Daniel', 11, 20, '&nbsp;د هغۀ په ځائ به بل بادشاه راشى هغه به محصُول اخستونکى ولېږى چې شاهى شان و شوکت پرې وساتى. خو په لږو ورځو کښې به هغه تباه شى، خو نۀ د غصې په وجه او نۀ د جنګ په وجه.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(20942, 'Daniel 11:21', 'Daniel', 11, 21, '&nbsp;د هغۀ په ځائ به يو بدعمله سړے بادشاه شى چې د بادشاهۍ حق به ورته نۀ وى حاصل. هغه به ناګهانه راښکاره شى، او په سلطنت به حمله وکړى، په چالاکۍ او ټګۍ سره به بادشاهۍ قبضه کړى.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(20943, 'Daniel 11:22', 'Daniel', 11, 22, '&nbsp;د هغۀ په وړاندې به لوئ لښکر جارُو شى، هغه او مشر اِمام به تباه شى.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(20944, 'Daniel 11:23', 'Daniel', 11, 23, '&nbsp;هغۀ سره د لوظ کولو نه پس به هغه د هغوئ سره دوکه وکړى او د لږو کسانو سره به هغه قدرت حاصل کړى.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(20945, 'Daniel 11:24', 'Daniel', 11, 24, '&nbsp;ناګهانه به مالداره صوبې ونيسى نو هغه به په هغوئ حمله وکړى او هغه هر څۀ به حاصل کړى چې د هغوئ پلار نيکۀ نۀ وو حاصل کړى. هغه به غنيمت، لوټ شوے دولت په خپلو ملګرو کښې تقسيم کړى. هغه به د قلعه ګانو د قبضه کولو منصوبې جوړې کړى خو دا به د لږ وخت دپاره وى.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(20946, 'Daniel 11:25', 'Daniel', 11, 25, '&nbsp;د يو لوئ لښکر سره به هغه زور ولګوى او په نرتوب به د جنوب بادشاه په خلاف جنګ وکړى. د جنوب بادشاه به هم د خپل لوئ او طاقتور لښکر سره جنګ وکړى، خو هغه به د شمال د بادشاه په وړاندې د هغه منصوبو په وجه ونۀ دريږى کومې يې چې د هغۀ په خلاف جوړې کړې دى.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(20947, 'Daniel 11:26', 'Daniel', 11, 26, '&nbsp;هغوئ څوک چې د بادشاه روټۍ خورى هغوئ به د هغۀ د تباه کولو کوشش وکړى، د هغۀ لښکر به ختم شى، او ډېر به په جنګ کښې مړۀ کړے شى.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(20948, 'Daniel 11:27', 'Daniel', 11, 27, '&nbsp;نو دواړه بادشاهان به د شېطانۍ نه ډکو زړونو سره په يو مېز کښېنى او يو بل ته به دروغ ووائى، خو يو به هم کامياب نۀ شى ځکه چې خاتمه به بيا هم په خپل مقرر وخت راشى.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(20949, 'Daniel 11:28', 'Daniel', 11, 28, '&nbsp;د شمال بادشاه به ډېر دولت سره خپل مُلک ته واپس شى، خو د هغۀ زړۀ به د مقدس لوظ خلاف شى. هغه به دې ته نقصان ورسوى او بيا به خپل مُلک ته واپس لاړ شى. ‏', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(20950, 'Daniel 11:29', 'Daniel', 11, 29, '&nbsp;په مقرر وخت به هغه بيا په جنوبى مُلک حمله وکړى، خو دې ځل به يې نتيجه د مخکښې نه بدله وى.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(20951, 'Daniel 11:30', 'Daniel', 11, 30, '&nbsp;د مغربى سمندر د غاړې کشتۍ به د هغۀ مخالف راشى، او هغه به زړۀ بائيلى. بيا به هغه واپس شى او خپله غصه به د مقدس لوظ په خلقو وباسى. هغه به واپس شى او په هغوئ به مهربان شى څوک چې مقدس لوظ هېروى.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(20952, 'Daniel 11:31', 'Daniel', 11, 31, '&nbsp;د هغۀ لښکر به راشى چې د عبادتګاه بې‌حرمتى وکړى او روزانه قربانۍ به بندې کړى. هغوئ به هلته هغه ناپاکه بُت ودروى کوم چې به تباهى راولى.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(20953, 'Daniel 11:32', 'Daniel', 11, 32, '&nbsp;بادشاه به په غوړو خبرو سره هغوئ دوکه کړى چا چې لوظ مات کړے دے، خو کوم خلق چې خپل خُدائ پاک پېژنى هغوئ به زورَور وى او د هغۀ مقابله به وکړى.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(20954, 'Daniel 11:33', 'Daniel', 11, 33, '&nbsp;څوک چې هوښيار دى هغوئ به ډېرو ته صحيح تعليم ورکړى، خو د څۀ وخت دپاره به هغوئ په تُوره قتل کړے شى يا به وسوزولے شى يا به قېد کړے شى او يا به لوټ کړے شى.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(20955, 'Daniel 11:34', 'Daniel', 11, 34, '&nbsp;کله چې هغوئ راپرېوځى ورته به صرف لږ مدد مِلاو شى، او ډېر چې مخلص نۀ دى ورسره به ملګرى شى.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(20956, 'Daniel 11:35', 'Daniel', 11, 35, '&nbsp;څۀ هوښياران به قتل کړے شى، د دې دپاره چې د آخر وخت پورې صفا، خالص او بې‌داغه کړے شى ځکه چې مقرر وخت راتلونکے دے.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(20957, 'Daniel 11:36', 'Daniel', 11, 36, '&nbsp;بادشاه به هغه څۀ کوى څۀ چې يې زړۀ غواړى. هغه به خپل ځان د هر معبود نه اوچت او لوئ ګڼى او د خُدائ پاک خلاف به هم کُفر وائى څوک چې د ټولو معبودانو خُدائ پاک دے. هغه به کامياب شى تر هغه وخته چې د غضب وخت پوره شوے نۀ وى، ځکه څۀ چې وئيلے شوى دى هغه به پوره کيږى.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(20958, 'Daniel 11:37', 'Daniel', 11, 37, '&nbsp;هغه به د خپل پلار نيکۀ معبودانو له عزت نۀ ورکوى او نۀ هغه معبود له کوم چې د ښځو خوښ دے، او نۀ به د يو معبود عزت کوى، خو هغه به خپل ځان د دې ټولو نه اوچت ګڼى.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(20959, 'Daniel 11:38', 'Daniel', 11, 38, '&nbsp;د دې په ځائ به هغه د قلعه ګانو د معبود عزت وکړى، د هغه معبود کوم چې د دۀ پلار نيکۀ نۀ پېژندلو. هغه به د هغۀ عزت د سرو او سپينو زرو او قيمتى کاڼو او قيمتى تُحفو ورکولو سره وکړى.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(20960, 'Daniel 11:39', 'Daniel', 11, 39, '&nbsp;هغه به د پردى معبود په مدد سره په مضبوطو قلعه ګانو حمله وکړى او د هغوئ به ډېر عزت کوى څوک چې د هغۀ حکومت منى. هغه به هغوئ په ډېرو خلقو حکمرانان مقرر کړى او په اجر کښې به په هغوئ زمکه تقسيم کړى.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(20961, 'Daniel 11:40', 'Daniel', 11, 40, '&nbsp;په آخر وخت کښې به د جنوب بادشاه هغۀ سره په جنګ شى، او د شمال بادشاه به د هغۀ خلاف د جنګى ګا‌ډو او آسونو سوارو او ډېرو سمندرى کشتو سره راوځى. هغه به په ډېرو مُلکونو حمله وکړى او هغوئ به لکه د سېلاب غوندې ختم کړى.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(20962, 'Daniel 11:41', 'Daniel', 11, 41, '&nbsp;هغه به په ښائسته مُلک حمله وکړى. ډېر مُلکونه به شکست وخورى، خو ادوم، موآب او د عمون مشران به د هغۀ د لاس نه بچ شى.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(20963, 'Daniel 11:42', 'Daniel', 11, 42, '&nbsp;هغه به خپل حکومت په ډېرو مُلکونو ومنى، او مِصر به ترې هم خلاص نۀ شى.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(20964, 'Daniel 11:43', 'Daniel', 11, 43, '&nbsp;هغه به د مِصر د سرو او سپينو خزانې او ټول دولت قبضه کړى، او ليبيا او ايتهوپيا به هم هغۀ ته تسليم شى.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(20965, 'Daniel 11:44', 'Daniel', 11, 44, '&nbsp;خو بيا به د مشرق او شمال افواګانې هغه پرېشانه کړى، او هغه به په ډېره غصه کښې راوځى چې ډېر خلق تباه او نيست و نابود کړى.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(20966, 'Daniel 11:45', 'Daniel', 11, 45, '&nbsp;هغه به شاهى خېمې د سمندر او د ښائسته مقدس غرۀ په مينځ کښې ولګوى. بيا هم به د هغۀ خاتمه راشى، او هيڅ څوک به د هغۀ مدد نۀ کوى.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(20967, 'Daniel 12:1', 'Daniel', 12, 1, '&nbsp;په هغه وخت کښې به ميکائيل، د فرښتو لوئ سردار څوک چې ستا د قوم حفاظت کوى، راوچت شى. هغه به داسې د مصيبت وخت وى چې داسې به د قومونو د پېدايښت نه تر دې وخت پورې نۀ وى شوے. خو په هغه وخت کښې به ستا د قوم نه هغوئ بچ شى، د چا نوم چې د خُدائ پاک په کِتاب کښې ليکلے شوے وى.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(20968, 'Daniel 12:2', 'Daniel', 12, 2, '&nbsp;نو بيا به هغه ګڼ خلق څوک چې په خاورو کښې پراتۀ دى راپاڅى، څوک به د ابدى ژوند دپاره، او څوک د رسوائى او ابدى شرم دپاره.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(20969, 'Daniel 12:3', 'Daniel', 12, 3, '&nbsp;څوک چې هوښيار دى د نمر د شغلو په شان به ځليږى، او هغوئ څوک چې ډېرو خلقو ته د صداقت لارښودنه کوى، هغوئ به لکه د ستورو په شان د تل دپاره ځليږى.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(20970, 'Daniel 12:4', 'Daniel', 12, 4, '&nbsp;خو تۀ اے دانياله، دا کلام بند کړه او تر آخرى زمانې پورې پرې مهر ولګوه. ډېر خلق به اخوا ديخوا ګرځى چې خپل عِلم کښې اضافه وکړى.“', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(20971, 'Daniel 12:5', 'Daniel', 12, 5, '&nbsp;بيا ما دانيال وکتل چې زما په وړاندې دوه نور سړى ولاړ وُو، يو د سيند په دې غاړه او بل پورې غاړه ولاړ وو.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(20972, 'Daniel 12:6', 'Daniel', 12, 6, '&nbsp;په هغوئ کښې يو د هغه سړى نه تپوس وکړو چې د کتان جامې يې اغوستې وې، او څوک چې د اوبو په غاړه ولاړ وو، ”نو دا حېرانېدونکې خبرې به نور په څومره وخت کښې پوره شى؟“', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(20973, 'Daniel 12:7', 'Daniel', 12, 7, '&nbsp;د کتان د جامو والا سړى څوک چې د اوبو دپاسه وو هغۀ خپل دواړه لاسونه آسمان ته اوچت کړل او ما واورېدل چې هغۀ د ژوندى خُدائ پاک په نوم قسم وخوړو او وې فرمائيل، ”دا به د درې نيمو کالو پورې وى. کله چې په مقدسو خلقو ظلم ختم شى نو بيا به دا هر څۀ سر ته ورسيږى.“', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(20974, 'Daniel 12:8', 'Daniel', 12, 8, '&nbsp;ما دا هر څۀ واورېدل، خو پوهه پرې نۀ شوم. نو ما ترې تپوس وکړو، ”زما مالِکه، د دې ټولو خبرو به څۀ اَنجام وى؟“', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(20975, 'Daniel 12:9', 'Daniel', 12, 9, '&nbsp;نو هغۀ جواب راکړو، ”اے دانياله، په خپله لار په آرام سره لاړ شه، ځکه چې تر آخره وخته پورې به کلام بند شى او مهر به پرې لګېدلے وى.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(20976, 'Daniel 12:10', 'Daniel', 12, 10, '&nbsp;ډېر به پاک، بې‌داغه او صفا کړے شى، خو بدعمله به بدعمله پاتې شى. يو بدعمله به پرې هم پوهه نۀ شى، خو هغوئ څوک چې هوښيار دى، هغوئ به پرې پوهه شى.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(20977, 'Daniel 12:11', 'Daniel', 12, 11, '&nbsp;د کوم وخت نه چې د روزانه قربانۍ ختمې شوې دى او د تباهۍ ناپاکه بُت اېښودے شوے دے، د هغې نه به دولس سوه او نوى ورځې تېرې شى.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(20978, 'Daniel 12:12', 'Daniel', 12, 12, '&nbsp;بختور دى هغوئ څوک چې ديارلس سوه او پينځۀ دېرش ورځو ختمېدو پورې صبر وکړى.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(20979, 'Daniel 12:13', 'Daniel', 12, 13, '&nbsp;ترڅو چې ستا تعلق دے په خپله لار تر آخره لاړ شه. تۀ به وفات شې، نو تۀ به په آخرى ورځو کښې بيا راژوندے شې د دې دپاره چې خپل ميراث درته مِلاو شى.“', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(20980, 'Hosea 1:1', 'Hosea', 1, 1, '&nbsp;مالِک خُدائ دا پېغام د بيرى په زوئ هوسيع باندې په هغه وخت کښې نازل کړو کله چې عُزياه، يوتام، احاز او حزقياه د يهوداه بادشاهان وُو او يربعام د يوآس زوئ د اِسرائيل بادشاه وو.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(20981, 'Hosea 1:2', 'Hosea', 1, 2, '&nbsp;کله چې مالِک خُدائ د بنى اِسرائيلو سره د هوسيع په ذريعه اول ځل خبرې وکړې، نو هغۀ هوسيع ته وفرمائيل، ”لاړ شه او زناکارې ښځې سره وادۀ وکړه، او حراميان بچى پېدا کړه، ځکه چې قوم د مالِک خُدائ فرمانبردارى پرېښې ده او په داسې کولو سره مسلسل زنا کوى.“', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(20982, 'Hosea 1:3', 'Hosea', 1, 3, '&nbsp;نو هوسيع لاړو او جُمر د دِبلائم لور سره يې وادۀ وکړو، هغه اُميدواره شوه او يو زوئ يې پېدا شو.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(20983, 'Hosea 1:4', 'Hosea', 1, 4, '&nbsp;نو مالِک خُدائ هوسيع ته وفرمائيل چې، ”په هغۀ باندې ”يزرعيل“ نوم کېږده، ځکه چې په لږ وخت کښې به زۀ د ياهُو بادشاه خاندان له سزا ورکړم، د هغه قتلونو انتقام به ترې نه واخلم کوم چې هغۀ په يزرعيل کښې کړى دى. او زۀ به د اِسرائيل بادشاهى هم ختمه کړم.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(20984, 'Hosea 1:5', 'Hosea', 1, 5, '&nbsp;په هغه ورځ به زۀ د يزرعيل په وادۍ کښې د اِسرائيل د فوجى لښکرو طاقت ختم کړم.“', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(20985, 'Hosea 1:6', 'Hosea', 1, 6, '&nbsp;جُمر يو ځل بيا اُميدواره شوه او په دې ځل يې يوه لور پېدا شوه. او مالِک خُدائ هوسيع ته وفرمائيل، ”په هغې باندې ”لو‌رحامه“ يعنې په چا چې رحم نۀ دے شوے نوم کېږده، ځکه چې زۀ به نور په بنى اِسرائيلو باندې رحم نۀ کوم، او نۀ به زۀ هغوئ معاف کوم.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(20986, 'Hosea 1:7', 'Hosea', 1, 7, '&nbsp;خو زۀ به د يهوداه په خلقو رحم کوم، زۀ به هغوئ د خپلو دشمنانو نه، نۀ په وسلو، او نۀ په لښکرو، نۀ په آسونو او نۀ په جنګى ګاډو، بلکې زۀ مالِک خُدائ د هغوئ خُدائ پاک به هغوئ په خپل زور او قدرت سره بچ کړم.“', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(20987, 'Hosea 1:8', 'Hosea', 1, 8, '&nbsp;کله چې جُمر خپله لور، لو‌رحامه د پيو نه منع کړه، نو هغه بيا اُميدواره شوه او دوېم زوئ يې پېدا شو.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(20988, 'Hosea 1:9', 'Hosea', 1, 9, '&nbsp;نو مالِک خُدائ هوسيع ته وفرمائيل، ”په هغۀ باندې ”لو‌عمى“ يعنې زما قوم نۀ دے نوم کېږده، ځکه چې بنى اِسرائيل زما خلق نۀ دى او زۀ د هغوئ خُدائ پاک نۀ يم.“', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(20989, 'Hosea 1:10', 'Hosea', 1, 10, '&nbsp;خو يو وخت راتلونکے دے چې بنى اِسرائيل به د سمندر د شګو په شان بې‌شمېره شى او څوک به يې نۀ شمېرلے شى او نۀ به يې څوک ناپ کولے شى. نو بيا په هغه ځائ کښې چرته چې هغوئ ته وئيلے شوى وُو چې، ”تاسو زما خلق نۀ يئ،“ هلته به هغوئ ته ووئيلے شى چې، ”تاسو د ژوندى خُدائ پاک بچى يئ.“', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(20990, 'Hosea 1:11', 'Hosea', 1, 11, '&nbsp;د يهوداه او اِسرائيل خلق به بيا په يو ځائ راغونډ شى او د ځان دپاره به يو مشر خوښ کړى. او هغوئ به په يو ځائ د جلاوطنۍ نه راواپس شى. نو دا به د يزرعيل دپاره يوه لويه ورځ وى.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(20991, 'Hosea 2:1', 'Hosea', 2, 1, '&nbsp;هغه وخت په خپلو وروڼو باندې ”عمى“ يعنې ”زما خلق“ او خپلو خوېندو باندې ”رحامه“ يعنې ”چې په چا رحم شوے وى“ نومونه کېږدئ.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(20992, 'Hosea 2:2', 'Hosea', 2, 2, '&nbsp;”خپله مور اِسرائيل ورټئ ځکه چې هغه زما ښځه نۀ ده او زۀ د هغې خاوند نۀ يم. هغې ته ووايئ چې د خپل مخ نه د کنجرتوب پرده لرې کړى او هغه خوشبوئى لرې کړى چې د هغې سينې څرګندوى.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(20993, 'Hosea 2:3', 'Hosea', 2, 3, '&nbsp;ګنې زۀ به هغه داسې بربنډه کړم لکه څنګه چې د پېدا کېدو په ورځ وه. زۀ به هغه د وچې او شاړې زمکې په شان کړم او د تندې د لاسه به يې ووژنم.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(20994, 'Hosea 2:4', 'Hosea', 2, 4, '&nbsp;زۀ به د هغې په بچو رحم نۀ کوم، ځکه چې هغوئ حراميان دى.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(20995, 'Hosea 2:5', 'Hosea', 2, 5, '&nbsp;او د هغوئ مور زنا کړې ده، د چا نه چې هغوئ پېدا دى هغوئ ډېر د شرم حرکتونه کړى دى. هغې وئيلى دى چې، ”زۀ به په خپلو عاشقانو پسې لاړه شم، ځکه چې هغوئ ما له خوراک، اوبۀ، وړۍ او د لټې جامې، د زيتُونو تېل او شراب راکوى.“', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(20996, 'Hosea 2:6', 'Hosea', 2, 6, '&nbsp;نو زۀ به هغه د ازغو په باړ کښې راګېره کړم او د هغې په لار کښې به يو دېوال جوړ کړم، چې د هغې نه خپله لاره ورکه شى.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(20997, 'Hosea 2:7', 'Hosea', 2, 7, '&nbsp;هغه به په خپلو عاشقانو پسې منډې وهى خو هغه به نۀ شى وررسېدے. هغه به خپل عاشقان لټوى خو پېدا به يې نۀ کړى. نو بيا به هغه ووائى، ”زۀ خپل خاوند له واپس ورځم. مخکښې زما ژوند د اوس نه ډېر ښۀ وو.“', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(20998, 'Hosea 2:8', 'Hosea', 2, 8, '&nbsp;هغې ته پته نۀ وه چې زۀ هغه ذات يم چا چې هغې له غله، مے، د زيتُونو تېل او هغه ډېر سرۀ زر او سپين زر ورکړل. خو هغې هغه هر څۀ بعل بُت ته په عبادت کښې پېش کړل.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(20999, 'Hosea 2:9', 'Hosea', 2, 9, '&nbsp;نو په دې وجه د لَو په وخت کښې به زۀ د هغې نه خپل د فصل او د انګورو د ميو نعمتونه واپس واخلم او کومه وړۍ او لټه چې ما ورکړې وه چې بربنډه نۀ شى هغه به ترې واخلم.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(21000, 'Hosea 2:10', 'Hosea', 2, 10, '&nbsp;زۀ به د هغې د عاشقانو په وړاندې د هغې شرم ښکاره کړم او هيڅوک به يې زما نه نۀ شى بچ کولے.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]');